import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/foundation.dart' show kIsWeb;
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:shared_preferences/shared_preferences.dart';

import 'client/client_app.dart';
import 'client/providers/client_cart_provider.dart';
// Generated by `flutterfire configure` (see SETUP.md). The portal shares the laboratory's
// Firebase project, so it reads the same live data.
import 'firebase_options.dart';

/// Entry point of the CLIENT PORTAL. The laboratory app keeps using `lib/main.dart`.
///
///   flutter run -d chrome -t lib/main_client.dart
///   flutter build web -t lib/main_client.dart
Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);

  // Same network workaround as the laboratory app (see lib/main.dart).
  if (kIsWeb) {
    FirebaseFirestore.instance.settings = const Settings(
      webExperimentalAutoDetectLongPolling: true,
    );
  }

  final prefs = await SharedPreferences.getInstance();

  runApp(ProviderScope(
    overrides: [sharedPreferencesProvider.overrideWithValue(prefs)],
    child: const ClientApp(),
  ));
}
